<script setup lang="ts">
import DismissibleNotice from './DismissibleNotice.vue';
import {ref,watch,onUnmounted} from 'vue';
const props=defineProps<{portrait?:Blob;disabled?:boolean}>();
const emit=defineEmits<{'update:portrait':[value:Blob|undefined];'update:avatar':[value:Blob|undefined];dirty:[]}>();
const canvas=ref<HTMLCanvasElement>(),input=ref<HTMLInputElement>(),zoom=ref(1),problem=ref(''),notice=ref(''),hasImage=ref(false);
let image:HTMLImageElement|undefined,url='',x=0,y=0,drag:{x:number;y:number;startX:number;startY:number}|undefined;
function paint(){const c=canvas.value,ctx=c?.getContext('2d');if(!c||!ctx||!image?.naturalWidth)return;const scale=Math.max(200/image.naturalWidth,200/image.naturalHeight)*zoom.value,w=image.naturalWidth*scale,h=image.naturalHeight*scale;x=Math.max(-(w-200)/2,Math.min((w-200)/2,x));y=Math.max(-(h-200)/2,Math.min((h-200)/2,y));ctx.clearRect(0,0,200,200);ctx.drawImage(image,(200-w)/2+x,(200-h)/2+y,w,h);}
async function crop(){if(!canvas.value||!hasImage.value)return;const out=document.createElement('canvas');out.width=512;out.height=512;out.getContext('2d')!.drawImage(canvas.value,0,0,512,512);const blob=await new Promise<Blob|null>(resolve=>out.toBlob(resolve,'image/png'));if(blob){emit('update:avatar',blob);emit('dirty');notice.value='头像裁剪已更新，保存档案后生效。';}}
watch(()=>props.portrait,async file=>{if(url)URL.revokeObjectURL(url);hasImage.value=false;notice.value='';if(!file){image=undefined;return;}url=URL.createObjectURL(file);const next=new Image();next.onload=()=>{image=next;x=0;y=0;zoom.value=1;hasImage.value=true;requestAnimationFrame(paint);};next.onerror=()=>{problem.value='图片无法读取，请更换文件。';};next.src=url;},{immediate:true});
async function select(event:Event){const el=event.target as HTMLInputElement,file=el.files?.[0];if(!file)return;problem.value='';try{if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>5*1024*1024)throw Error('请选择5MB以内的 PNG、JPEG 或 WebP 图片。');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>24000000){bitmap.close();throw Error('图片像素过大，请使用2400万像素以内的图片。');}bitmap.close();emit('update:portrait',file);emit('update:avatar',undefined);emit('dirty');}catch(error){problem.value=(error as Error).message;}finally{el.value='';}}
function down(event:PointerEvent){if(!hasImage.value||props.disabled)return;drag={x,y,startX:event.clientX,startY:event.clientY};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);}
function move(event:PointerEvent){if(!drag)return;const size=(event.currentTarget as HTMLElement).getBoundingClientRect().width;x=drag.x+(event.clientX-drag.startX)*200/size;y=drag.y+(event.clientY-drag.startY)*200/size;paint();}
onUnmounted(()=>{if(url)URL.revokeObjectURL(url);});
</script>
<template><section class="persona-image-editor"><h2>人设图片与头像</h2><div class="actions"><button type="button" :disabled="disabled" @click="input?.click()">选择图片</button><button v-if="portrait" type="button" :disabled="disabled" @click="emit('update:portrait',undefined);emit('update:avatar',undefined);emit('dirty')">移除图片</button><input ref="input" type="file" accept="image/png,image/jpeg,image/webp" hidden @change="select" /><small class="muted">PNG / JPEG / WebP · 最多5MB</small><slot name="image-options" /></div><div v-if="portrait" class="persona-crop-layout"><div class="persona-crop-preview"><canvas ref="canvas" width="200" height="200" aria-label="拖动图片调整头像裁剪" @pointerdown="down" @pointermove="move" @pointerup="drag=undefined" @pointercancel="drag=undefined" @lostpointercapture="drag=undefined" /></div><div><p>拖动图片调整位置，缩放后点击保存头像裁剪。</p><label>头像缩放<input v-model.number="zoom" type="range" min="1" max="3" step=".01" :disabled="disabled" @input="paint" /></label><button type="button" :disabled="disabled||!hasImage" @click="crop">保存头像裁剪</button><p class="muted">头像使用方形裁剪，档案保留完整原图。</p></div></div><DismissibleNotice :message="problem" error /><DismissibleNotice :message="notice" /></section></template>

